-- Разрешить вывод только в валютах A и B (запретить BC).
-- Старое ограничение: check (currency = 'BC').
-- Новое: check (currency in ('A','B')).
--
-- Запусти этот скрипт в Supabase → SQL Editor (один раз).

-- 1) Удаляем старое ограничение (имя у autogenerated может отличаться —
--    удаляем через поиск по таблице).
do $$
declare
  c record;
begin
  for c in
    select conname
    from pg_constraint
    where conrelid = 'public.withdrawals'::regclass
      and contype = 'c'
      and pg_get_constraintdef(oid) ilike '%currency%'
  loop
    execute format('alter table public.withdrawals drop constraint %I', c.conname);
  end loop;
end $$;

-- 2) Добавляем новое ограничение: только A и B.
alter table public.withdrawals
  add constraint withdrawals_currency_check check (currency in ('A','B'));

-- 3) Меняем дефолт на 'A'.
alter table public.withdrawals alter column currency set default 'A';
